"""原型：用「同一行上有多个横向分开的文本片段」当表格判据（图框/正文/页眉都过不了）。"""
import sys,re; sys.path.insert(0,'src')
import fitz
from papershelf.pipeline.parse import parse_pdf
from papershelf.pipeline.proofread import _h_rules, _flat

P='/tmp/pslocal/data/papers/2026-09-14T130316+0000_original.pdf'
GAP=220.0; PAD=6.0; MIN_LINES=4; MIN_RATIO=1.6; MIN_COLS=2

def page_lines(page):
    out=[]
    for blk in page.get_text('dict').get('blocks',[]):
        if blk.get('type')!=0: continue
        for ln in blk.get('lines',[]):
            t=''.join(s.get('text','') for s in ln.get('spans',[]))
            if not t.strip(): continue
            x0,y0,x1,y1=ln['bbox']
            out.append((x0,y0,x1,y1,t))
    return out

def regions(page):
    H,W=page.rect.height,page.rect.width
    rs=[r for r in _h_rules(page) if H*0.09<r[0]<H*0.94]
    if not rs: return []
    groups=[]
    for r in rs:
        if groups:
            last=groups[-1][-1]
            ov=min(last[2],r[2])-max(last[1],r[1])
            if r[0]-last[0]<=GAP and ov>0:
                groups[-1].append(r); continue
        groups.append([r])
    L=page_lines(page); out=[]
    for g in groups:
        y0,y1=g[0][0],g[-1][0]
        if y1-y0<8: continue
        x0=min(r[1] for r in g); x1=max(r[2] for r in g)
        inb=[l for l in L if l[1]>y0-PAD and l[3]<y1+PAD]
        rows={round(l[1]/4.0) for l in inb}
        cols={round(l[0]/4.0) for l in inb}
        ratio=(len(inb)/len(rows)) if rows else 0
        ok=len(inb)>=MIN_LINES and ratio>=MIN_RATIO and len(cols)>=MIN_COLS
        out.append(dict(y=(round(y0),round(y1)), x=(round(x0),round(x1)),
                        lines=len(inb), rows=len(rows), cols=len(cols),
                        ratio=round(ratio,2), ok=ok))
    return out

doc=parse_pdf(P, assets_dir=None); src=fitz.open(P)
by={}
for b in doc.blocks: by.setdefault(int(b.payload.get('page') or 0),[]).append(b)
hitpages=[]
for pno in range(1,38):
    for r in regions(src[pno-1]):
        mark='✅' if r['ok'] else '  '
        print(f"p{pno:2d} {mark} y{r['y']} x{r['x']} lines={r['lines']} rows={r['rows']} cols={r['cols']} ratio={r['ratio']}")
        if r['ok']: hitpages.append(pno)
print('REPORTED PAGES:', sorted(set(hitpages)))
