import sys; sys.path.insert(0,'src')
import fitz
from papershelf.pipeline.parse import parse_pdf
from papershelf.pipeline.proofread import _flat

P='/tmp/pslocal/data/papers/2026-09-14T130316+0000_original.pdf'
doc=parse_pdf(P, assets_dir=None); src=fitz.open(P)
by={}
for b in doc.blocks: by.setdefault(int(b.payload.get('page') or 0),[]).append(b)

def lines_of(page):
    out=[]
    for blk in page.get_text('dict').get('blocks',[]):
        if blk.get('type')!=0: continue
        for ln in blk.get('lines',[]):
            t=''.join(s.get('text','') for s in ln.get('spans',[]))
            if not t.strip(): continue
            x0,y0,x1,y1=ln['bbox']
            out.append((_flat(t),y0,y1,x0,x1))
    return out

def global_match(page,bs):
    res={}
    for (t,y0,y1,x0,x1) in lines_of(page):
        if len(t)<3: continue
        cands=[b for b in bs if t in _flat(b.en)]
        if not cands: continue
        b=min(cands,key=lambda b: len(b.en))       # 最"紧"的块优先
        res.setdefault(b.id,[]).append((y0,y1,x0,x1))
    return res

def spans_of(v):
    return (min(a[0] for a in v), max(a[1] for a in v), min(a[2] for a in v), max(a[3] for a in v))

